package cn.binbin.crm;

import jakarta.validation.constraints.*;
import java.time.LocalDate;
import java.util.*;
import org.springframework.stereotype.Service;
import static cn.binbin.crm.TradeService.*;

@Service
public class FinanceWorkspaceService {
 public record AccountInput(@NotBlank @Size(max=100) String name,@Size(max=120) String accountReference,@Min(-100000000000L) @Max(100000000000L) long openingCents,@NotNull LocalDate openingDate){}
 public record AccountState(boolean active,@Min(0) long expectedVersion){}
 public record InvoiceInput(@NotNull UUID contractId,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=200) String buyerName,@Size(max=80) String taxNumber,@Min(1) @Max(100000000000L) long amountCents,@Size(max=2000) String notes){}
 public record InvoiceAction(@Min(0) long expectedVersion,@Size(max=500) String reason,@Size(max=120) String reference,LocalDate businessDate,@Min(1) @Max(100000000000L) Long amountCents){}
 public record ExpenseInput(@NotNull UUID accountId,@NotBlank @Size(max=200) String payee,@NotBlank @Size(max=80) String category,@Min(1) @Max(100000000000L) long amountCents,@NotNull LocalDate paymentDate,@NotBlank @Size(max=120) String paymentReference,@Size(max=2000) String notes){}
 private final TradeService t;
 public FinanceWorkspaceService(TradeService t){this.t=t;}
 static boolean manager(AuthService.Actor a){return a.tenant().roles().contains("SALES_MANAGER")&&a.tradeAccess().confirm();}
 private void requireManager(AuthService.Actor a){if(!manager(a)||!a.tradeAccess().contracts().readAll())throw ApiError.forbidden("资金账户与支出审核需要全企业财务复核权限");}
 private void businessDate(LocalDate d){date(d);if(d.isAfter(today()))throw ApiError.bad("业务日期不能晚于今天");}
 private void version(Map<String,Object> row,long expected){if(number(row,"version")!=expected)throw ApiError.conflict("单据已变化，请刷新");}
 private String code(String prefix,UUID id){return prefix+today().toString().replace("-","")+"-"+id.toString().replace("-","").substring(0,16).toUpperCase(Locale.ROOT);}
 private void separate(AuthService.Actor a,UUID creator){UUID user=t.db.queryForObject("SELECT user_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",creator),UUID.class);if(a.session().userId().equals(user))throw ApiError.forbidden("需由另一位财务复核人审核，不能审核本人登记");}
 Map<String,Object> account(AuthService.Actor a,UUID id,boolean active){var r=t.one("SELECT * FROM crm_fund_account WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));if(active&&!Boolean.TRUE.equals(r.get("active")))throw ApiError.conflict("资金账户已停用");return r;}
 public Object accountOptions(AuthService.Session s){return t.scoped(s,"receipt",false,a->map("items",t.rows("SELECT id,name,active FROM crm_fund_account WHERE tenant_id=:tenant ORDER BY name",map("tenant",a.tenant().id()))));}
 public Object accounts(AuthService.Session s){return t.scoped(s,"reconcile",false,a->{requireManager(a);return map("items",t.rows("SELECT f.*,(SELECT coalesce(sum(e.delta_cents),0)::bigint FROM crm_fund_entry e WHERE e.tenant_id=f.tenant_id AND e.account_id=f.id) AS balance_cents FROM crm_fund_account f WHERE f.tenant_id=:tenant ORDER BY f.created_at DESC",map("tenant",a.tenant().id())),"unallocatedReceivedCents",t.db.queryForObject("SELECT coalesce(sum(amount_cents),0)-(SELECT coalesce(sum(v.amount_cents),0) FROM crm_receipt_reversal v JOIN crm_receipt z ON z.tenant_id=v.tenant_id AND z.id=v.receipt_id WHERE z.tenant_id=:tenant AND z.fund_account_id IS NULL) FROM crm_receipt WHERE tenant_id=:tenant AND fund_account_id IS NULL AND status IN('CONFIRMED','REVERSED')",map("tenant",a.tenant().id()),Long.class));});}
 public Object createAccount(AuthService.Session s,AccountInput i,String key,UUID trace){businessDate(i.openingDate());return t.scoped(s,"confirm",true,a->{requireManager(a);UUID id=t.once(a,"fund.account.create",key,i,()->{UUID n=UUID.randomUUID();t.db.update("INSERT INTO crm_fund_account(id,tenant_id,name,account_reference) VALUES(:id,:tenant,:name,:ref)",map("id",n,"tenant",a.tenant().id(),"name",text(i.name()),"ref",text(i.accountReference())));post(a,n,"OPENING",n,i.openingCents(),i.openingDate(),"期初余额","");event(a,"ACCOUNT",n,0,"CREATED","",account(a,n,false),trace);return n;});return account(a,id,false);});}
 public Object accountState(AuthService.Session s,UUID id,AccountState i,UUID trace){return t.scoped(s,"confirm",true,a->{requireManager(a);version(account(a,id,false),i.expectedVersion());t.db.update("UPDATE crm_fund_account SET active=:active,version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"active",i.active()));var r=account(a,id,false);event(a,"ACCOUNT",id,number(r,"version"),i.active()?"ACTIVATED":"DISABLED","",r,trace);return r;});}
 void post(AuthService.Actor a,UUID account,String kind,UUID source,long delta,LocalDate date,String reference,String notes){t.db.update("INSERT INTO crm_fund_entry(id,tenant_id,account_id,source_type,source_id,delta_cents,business_date,reference,notes,actor_member_id) VALUES(:id,:tenant,:account,:kind,:source,:delta,:date,:ref,:notes,:member)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"account",account,"kind",kind,"source",source,"delta",delta,"date",date,"ref",text(reference),"notes",text(notes),"member",a.tenant().memberId()));}
 public Object ledger(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return t.scoped(s,"reconcile",false,a->{requireManager(a);var f=account(a,id,false);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);var rows=t.rows("SELECT * FROM(SELECT e.*,sum(delta_cents) OVER(ORDER BY business_date,created_at,id)::bigint AS balance_cents FROM crm_fund_entry e WHERE tenant_id=:tenant AND account_id=:id) x ORDER BY business_date DESC,created_at DESC,id DESC LIMIT :limit OFFSET :offset",p);return map("account",f,"items",rows,"total",t.db.queryForObject("SELECT count(*) FROM crm_fund_entry WHERE tenant_id=:tenant AND account_id=:id",p,Long.class));});}
 private static final String IFROM=FROM+" JOIN crm_invoice i ON i.tenant_id=k.tenant_id AND i.contract_id=k.id ";
 private static final String ISELECT="SELECT i.*,k.contract_number,k.order_id,k.customer_name_snapshot,k.total_cents AS contract_total_cents"+IFROM;
 Map<String,Object> invoice(AuthService.Actor a,UUID id){var p=t.params(a);p.put("id",id);var r=t.one(ISELECT+" WHERE "+READ+" AND i.id=:id",p);r.put("canWrite",a.tradeAccess().receiptWrite()&&a.tenant().memberId().equals(r.get("createdByMemberId")));r.put("canApprove",manager(a));r.put("reds",t.rows("SELECT * FROM crm_invoice_red WHERE tenant_id=:tenant AND invoice_id=:id ORDER BY created_at DESC",p));return r;}
 public Object invoices(AuthService.Session s,int page,int size,String q,UUID contract){page(page,size,q);return t.scoped(s,"receipt",false,a->{var p=t.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"contract",contract,"limit",size,"offset",((long)page-1)*size));String w=READ+" AND(cast(:contract AS uuid) IS NULL OR i.contract_id=:contract) AND(:q='' OR strpos(lower(i.invoice_number||' '||i.title||' '||k.contract_number),:q)>0)";return new BusinessService.Page<>(t.rows(ISELECT+" WHERE "+w+" ORDER BY i.created_at DESC,i.id LIMIT :limit OFFSET :offset",p),page,size,t.db.queryForObject("SELECT count(*)"+IFROM+" WHERE "+w,p,Long.class));});}
 public Object invoice(AuthService.Session s,UUID id){return t.scoped(s,"receipt",false,a->invoice(a,id));}
 public Object invoiceCreate(AuthService.Session s,InvoiceInput i,String key,UUID trace){return t.scoped(s,"receipt",true,a->{UUID id=t.once(a,"invoice.create",key,i,()->{var k=t.contract(a,i.contractId());if(!Set.of("SIGNED","ACTIVE","TERMINATED").contains(k.get("status")))throw ApiError.conflict("开票申请需要已签订合同");long reserved=t.db.queryForObject("SELECT coalesce(sum(amount_cents-red_cents),0)::bigint FROM crm_invoice WHERE tenant_id=:tenant AND contract_id=:contract AND status<>'VOID'",map("tenant",a.tenant().id(),"contract",i.contractId()),Long.class);if(i.amountCents()>number(k,"totalCents")-reserved)throw ApiError.conflict("申请超过合同未占用开票余额，请检查已有申请");UUID n=UUID.randomUUID();t.db.update("INSERT INTO crm_invoice(id,tenant_id,contract_id,invoice_number,title,buyer_name,tax_number,amount_cents,notes,created_by_member_id) VALUES(:id,:tenant,:contract,:number,:title,:buyer,:tax,:amount,:notes,:member)",map("id",n,"tenant",a.tenant().id(),"contract",i.contractId(),"number",code("IV",n),"title",text(i.title()),"buyer",text(i.buyerName()),"tax",text(i.taxNumber()),"amount",i.amountCents(),"notes",text(i.notes()),"member",a.tenant().memberId()));event(a,"INVOICE",n,0,"CREATED","",invoice(a,n),trace);return n;});return invoice(a,id);});}
 public Object invoiceAction(AuthService.Session s,UUID id,String action,InvoiceAction i,String key,UUID trace){boolean approve=Set.of("approve","reject","issue","red").contains(action);return t.scoped(s,approve?"confirm":"receipt",true,a->{UUID selected=t.once(a,"invoice."+action,key,new TradeService.Target(id,i),()->{var r=invoice(a,id);version(r,i.expectedVersion());String state=(String)r.get("status"),next=state;boolean own=a.tenant().memberId().equals(r.get("createdByMemberId"));String reason=text(i.reason());var p=map("tenant",a.tenant().id(),"id",id,"ref",null,"date",null,"approver",r.get("approvedByMemberId"));switch(action){
 case "submit"->{if(!own||!state.equals("DRAFT"))throw ApiError.forbidden("仅申请人可提交草稿");next="SUBMITTED";}
 case "approve","reject"->{separate(a,(UUID)r.get("createdByMemberId"));if(!state.equals("SUBMITTED"))throw ApiError.conflict("只可审核待审批申请");if(action.equals("reject")&&reason.isEmpty())throw ApiError.bad("填写退回原因");next=action.equals("approve")?"APPROVED":"DRAFT";p.put("approver",action.equals("approve")?a.tenant().memberId():null);}
 case "issue"->{if(!state.equals("APPROVED"))throw ApiError.conflict("先审核申请，再登记实际发票");businessDate(i.businessDate());p.put("ref",FinanceService.reference(i.reference()));p.put("date",i.businessDate());next="ISSUED";}
 case "void"->{if(!own&&!manager(a))throw ApiError.forbidden("无权作废该申请");if(!Set.of("DRAFT","SUBMITTED","APPROVED").contains(state)||reason.isEmpty())throw ApiError.conflict("仅未开票申请可填写原因作废");next="VOID";}
 case "red"->{if(!state.equals("ISSUED")||i.amountCents()==null||i.amountCents()>number(r,"amountCents")-number(r,"redCents")||reason.isEmpty())throw ApiError.bad("红冲金额超限或缺少原因");businessDate(i.businessDate());if(i.businessDate().isBefore((LocalDate)r.get("issuedDate")))throw ApiError.bad("红冲日期不能早于开票日期");t.db.update("INSERT INTO crm_invoice_red(id,tenant_id,invoice_id,amount_cents,red_reference,red_date,reason,actor_member_id) VALUES(:red,:tenant,:id,:amount,:ref,:date,:reason,:member)",map("red",UUID.randomUUID(),"tenant",a.tenant().id(),"id",id,"amount",i.amountCents(),"ref",FinanceService.reference(i.reference()),"date",i.businessDate(),"reason",reason,"member",a.tenant().memberId()));t.db.update("UPDATE crm_invoice SET red_cents=red_cents+:amount WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"amount",i.amountCents()));}
 default->throw ApiError.bad("开票操作无效");}
 p.put("state",next);t.db.update("UPDATE crm_invoice SET status=:state,approved_by_member_id=:approver,invoice_reference=coalesce(cast(:ref AS varchar),invoice_reference),issued_date=coalesce(cast(:date AS date),issued_date),version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",p);var updated=invoice(a,id);event(a,"INVOICE",id,number(updated,"version"),action.toUpperCase(Locale.ROOT),reason,updated,trace);return id;});return invoice(a,selected);});}
 Map<String,Object> expense(AuthService.Actor a,UUID id){var r=t.one("SELECT e.*,m.display_name AS creator_name FROM crm_expense e JOIN sys_tenant_member m ON m.tenant_id=e.tenant_id AND m.id=e.created_by_member_id WHERE e.tenant_id=:tenant AND e.id=:id AND(:all OR e.created_by_member_id=:member)",map("tenant",a.tenant().id(),"id",id,"all",manager(a)&&a.tradeAccess().contracts().readAll(),"member",a.tenant().memberId()));return r;}
 public Object expenses(AuthService.Session s,int page,int size){page(page,size,"");return t.scoped(s,"receipt",false,a->{var p=map("tenant",a.tenant().id(),"all",manager(a)&&a.tradeAccess().contracts().readAll(),"member",a.tenant().memberId(),"limit",size,"offset",((long)page-1)*size);String w="e.tenant_id=:tenant AND(:all OR e.created_by_member_id=:member)";return new BusinessService.Page<>(t.rows("SELECT e.*,f.name AS account_name FROM crm_expense e JOIN crm_fund_account f ON f.tenant_id=e.tenant_id AND f.id=e.account_id WHERE "+w+" ORDER BY e.created_at DESC LIMIT :limit OFFSET :offset",p),page,size,t.db.queryForObject("SELECT count(*) FROM crm_expense e WHERE "+w,p,Long.class));});}
 public Object expenseCreate(AuthService.Session s,ExpenseInput i,String key,UUID trace){businessDate(i.paymentDate());return t.scoped(s,"receipt",true,a->{UUID id=t.once(a,"expense.create",key,i,()->{account(a,i.accountId(),true);UUID n=UUID.randomUUID();t.db.update("INSERT INTO crm_expense(id,tenant_id,account_id,expense_number,payee,category,amount_cents,payment_date,payment_reference,notes,created_by_member_id) VALUES(:id,:tenant,:account,:number,:payee,:category,:amount,:date,:ref,:notes,:member)",map("id",n,"tenant",a.tenant().id(),"account",i.accountId(),"number",code("EX",n),"payee",text(i.payee()),"category",text(i.category()),"amount",i.amountCents(),"date",i.paymentDate(),"ref",FinanceService.reference(i.paymentReference()),"notes",text(i.notes()),"member",a.tenant().memberId()));event(a,"EXPENSE",n,0,"CREATED","",expense(a,n),trace);return n;});return expense(a,id);});}
 public Object expenseAction(AuthService.Session s,UUID id,String action,InvoiceAction i,String key,UUID trace){return t.scoped(s,action.equals("void")?"receipt":"confirm",true,a->{UUID selected=t.once(a,"expense."+action,key,new TradeService.Target(id,i),()->{var r=expense(a,id);version(r,i.expectedVersion());String state=(String)r.get("status"),next;String reason=text(i.reason());if(action.equals("confirm")){requireManager(a);separate(a,(UUID)r.get("createdByMemberId"));if(!state.equals("DRAFT"))throw ApiError.conflict("只可确认待审核支出");account(a,(UUID)r.get("accountId"),true);post(a,(UUID)r.get("accountId"),"EXPENSE",id,-number(r,"amountCents"),(LocalDate)r.get("paymentDate"),(String)r.get("paymentReference"),reason);next="CONFIRMED";}else if(action.equals("reverse")){requireManager(a);if(!state.equals("CONFIRMED")||reason.isEmpty())throw ApiError.conflict("仅已确认支出可填写原因冲正");businessDate(i.businessDate());if(i.businessDate().isBefore((LocalDate)r.get("paymentDate")))throw ApiError.bad("冲正日期不能早于付款日期");post(a,(UUID)r.get("accountId"),"EXPENSE_REVERSAL",id,number(r,"amountCents"),i.businessDate(),(String)r.get("paymentReference"),reason);next="REVERSED";}else if(action.equals("void")){if(!state.equals("DRAFT")||!a.tenant().memberId().equals(r.get("createdByMemberId"))||reason.isEmpty())throw ApiError.forbidden("仅登记人可填写原因作废待审核支出");next="VOID";}else throw ApiError.bad("支出操作无效");t.db.update("UPDATE crm_expense SET status=:state,confirmed_by_member_id=CASE WHEN :state='CONFIRMED' THEN :member ELSE confirmed_by_member_id END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"member",a.tenant().memberId(),"state",next));var updated=expense(a,id);event(a,"EXPENSE",id,number(updated,"version"),action.toUpperCase(Locale.ROOT),reason,updated,trace);return id;});return expense(a,selected);});}
 public Object orderBalances(AuthService.Session s,UUID order){return t.scoped(s,"receipt",false,a->{var p=t.params(a);p.put("order",order);var k=t.one("SELECT k.id,k.order_id,k.total_cents,"+CASH+"::bigint AS received_cents"+FROM+" WHERE "+READ+" AND k.order_id=:order",p);UUID contract=(UUID)k.get("id");long invoiced=t.db.queryForObject("SELECT coalesce(sum(amount_cents-red_cents),0)::bigint FROM crm_invoice WHERE tenant_id=:tenant AND contract_id=:contract AND status='ISSUED'",map("tenant",a.tenant().id(),"contract",contract),Long.class);k.put("invoicedCents",invoiced);k.put("uninvoicedCents",number(k,"totalCents")-invoiced);k.put("unreceivedCents",number(k,"totalCents")-number(k,"receivedCents"));return k;});}
 private void event(AuthService.Actor a,String type,UUID id,long version,String action,String reason,Object snapshot,UUID trace){t.db.update("INSERT INTO crm_finance_event(id,tenant_id,entity_type,entity_id,business_version,action,reason,snapshot,actor_member_id) VALUES(:event,:tenant,:type,:id,:version,:action,:reason,cast(:snapshot AS jsonb),:member)",map("event",UUID.randomUUID(),"tenant",a.tenant().id(),"type",type,"id",id,"version",version,"action",action,"reason",reason,"snapshot",t.body(snapshot),"member",a.tenant().memberId()));t.audit(a,type+"_"+action,type,id,version,trace);}
 public Object history(AuthService.Session s,String type,UUID id){return t.scoped(s,"receipt",false,a->{switch(type){case "INVOICE"->invoice(a,id);case "EXPENSE"->expense(a,id);case "ACCOUNT"->{requireManager(a);account(a,id,false);}default->throw ApiError.bad("财务单据类型无效");}return map("items",t.rows("SELECT e.business_version,e.action,e.reason,e.created_at,m.display_name AS actor_name FROM crm_finance_event e JOIN sys_tenant_member m ON m.tenant_id=e.tenant_id AND m.id=e.actor_member_id WHERE e.tenant_id=:tenant AND e.entity_type=:type AND e.entity_id=:id ORDER BY business_version DESC",map("tenant",a.tenant().id(),"type",type,"id",id)));});}
 public Object workspaceExpense(AuthService.Session s,UUID id){return t.scoped(s,"receipt",false,a->{var r=expense(a,id);r.put("canWrite",a.tradeAccess().receiptWrite()&&a.tenant().memberId().equals(r.get("createdByMemberId"))&&"DRAFT".equals(r.get("status")));return r;});}
}
